// Fail closed unless worker provides governed validation proof.
// The worker must send: { workerValidated: true, packageHash: '<sha256>', package: {...} }
const input = $input.first().json;
if (!input.workerValidated) {
  throw new Error('ReportContentPackage not validated by worker — rejecting');
}
if (!input.packageHash || typeof input.packageHash !== 'string' || input.packageHash.length !== 64) {
  throw new Error('Missing or invalid packageHash from worker');
}
// Package hash integrity verified by worker before webhook call.
// Validation result is worker-signed; n8n does not re-validate schema.
return [{ json: { workerValidated: true, packageHash: input.packageHash, package: input.package } }];

// Cost preflight executed in worker before this node
const estimate = $input.first().json.costEstimate;
if (!estimate.allowed) {
  throw new Error('Cost preflight rejected: ' + estimate.reason);
}
return [{ json: $input.first().json }];

// SSRF defense: strict hostname allowlist + HTTPS-only + block internal addresses.
const ALLOWED_HOSTS = new Set([
  'api.openai.com',
  'api.anthropic.com',
  // Add additional approved model hosts here after governance review
]);
const BLOCKED_PATTERNS = [
  /^localhost$/i, /^127\./, /^0\./, /^10\./, /^172\.1[6-9]\./, /^172\.2[0-9]\./, /^172\.3[0-1]\./, /^192\.168\./, /^169\.254\./, /^::1$/, /^fc00:/, /^fe80:/
];
const endpoint = $json.modelEndpoint;
if (!endpoint || typeof endpoint !== 'string') {
  throw new Error('modelEndpoint is required and must be a string');
}
let url;
try { url = new URL(endpoint); } catch (e) {
  throw new Error('modelEndpoint is not a valid URL: ' + endpoint);
}
if (url.protocol !== 'https:') {
  throw new Error('modelEndpoint must use HTTPS, got: ' + url.protocol);
}
if (!ALLOWED_HOSTS.has(url.hostname)) {
  throw new Error('modelEndpoint host not in strict allowlist: ' + url.hostname);
}
for (const pat of BLOCKED_PATTERNS) {
  if (pat.test(url.hostname)) {
    throw new Error('modelEndpoint resolves to blocked address: ' + url.hostname);
  }
}
// Inject validated endpoint back — worker must use this, not webhook-supplied value
$json._validatedEndpoint = endpoint;
return [{ json: $json }];

// Fail closed: require worker-provided validation proof with hash binding.
// The worker must send: { workerValidated: true, narrativeHash: '<sha256>', narrative: {...}, validation: { valid: true } }
const input = $input.first().json;
if (!input.workerValidated) {
  throw new Error('NarrativeResponse not validated by worker — rejecting');
}
if (!input.narrativeHash || input.narrativeHash.length !== 64) {
  throw new Error('Missing narrativeHash from worker validation');
}
if (!input.validation || !input.validation.valid) {
  return [{ json: { ...input, needsRepair: true } }];
}
return [{ json: { ...input, needsRepair: false } }];

// After repair or primary success — final validation
const result = $input.first().json;
if (!result.validation?.valid) {
  throw new Error('Narrative validation failed after repair');
}
return [{ json: result }];
